// ==UserScript==
// @name         Avali Scratch/Script Website Font Changer
// @namespace    https://github.com/skyebluemango/TM-Avali-Scratch
// @version      1.1
// @description  converts all text on webpage to avali scratch or avali script
// @author       @mangodreams.bsky.social on bluesky
// @match        http*://*/*
// ==/UserScript==

/*
* Drag image from https://icons.iconarchive.com/icons/arturo-wibawa/akar/24/drag-horizontal-icon.png
* Uses font “Avali Scratch” (https://fontstruct.com/fontstructions/show/1108804/avali_scratch) by “AikaDee”
* Uses font "Avali Script" (https://fontstruct.com/fontstructions/show/2809369/avali-script) by "AikaDee"
*/

const style = "<style id=\"Avali Scratch Font\">.scratch {font-family: avali_scratchregular !important}\n.learner:not(:hover){font-family: avali_scratchregular !important}\n" +
      ".script {font-family: avali_script !important}\n.learner_script:not(:hover){font-family: avali_script !important}</style>";

(function() {
    'use strict';
    // try to relax trusted type policy
    try{
    window.trustedTypes.createPolicy('default', {createHTML: (string, sink) => string});
    } catch (err) {}

    // put font in header
    const fontStyle = document.createElement("style");
    fontStyle.innerText = `@font-face {
    font-family: 'avali_scratchregular';
    src: url(data:font/truetype;charset=utf-8;base64,) format('truetype');
    font-weight: normal;
    font-style: normal;
    }
    @font-face {
    font-family: "avali_script";
    src: url(data:application/octet-stream;base64,);
    }
    `;
    document.head.appendChild(fontStyle);

    // create helper buttons
    const toggle = document.createElement("div");
    toggle.innerHTML = `
    <!-- image: https://icons.iconarchive.com/icons/arturo-wibawa/akar/24/drag-horizontal-icon.png -->
    <img src="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABgAAAAYCAYAAADgdz34AAAACXBIWXMAAA7EAAAOxAGVKw4bAAAASUlEQVRIx2NgGAWjgJoggIGB4QUUB9BAnuEFAwPDfyh+gUf+HynyLMMqiEbBCMkH/wikc5Ll0fMBIwFfMkIzE1nyo/lgFAxSAAB3OjYWxXkRRgAAAABJRU5ErkJggg==">
    <label>Toggle</label>
    <input id="toggleFontChange" onchange="toggleFont" type="checkbox">
    <label>Learner Mode</label>
    <input id="toggleLearnerMode" onchange="toggleFont" type="checkbox">
    <div>
    <input id="fontRadio_scratch" type=\"radio\" name=font value=scratch onchange="toggleFont" checked>
    <label for=scratch>Avali scratch</label>
    <input id="fontRadio_script" type=\"radio\" name=font value=script onchange="toggleFont">
    <label for=script>Avali script</label>
    </div>
    <style>
    @keyframes opacityHover {
    0% {opacity: 50%;}
    100% {opacity: 100%;}
    }
    @keyframes opacityDef {
    0% {opacity: 100%;}
    100% {opacity: 50%;}
    }

    #FONTCONTROLLER {
    all: initial;

    line-height: 16px;

    position: fixed;
    left: 10px;
    bottom: 10px;
    z-index: 1000000;

    background-color: gray;
    opacity: 50%;
    border: solid 2px gray;
    border-radius: 2px;

    cursor: move;
    }

    #FONTCONTROLLER:not(:hover){
    animation-name: opacityDef;
    animation-duration: 100ms;
    animation-fill-mode: forwards;
    }

    #FONTCONTROLLER:hover {
    animation-name: opacityHover;
    animation-duration: 100ms;
    animation-fill-mode: forwards;
    }

    #FONTCONTROLLER label, #FONTCONTROLLER div {
    font-size: 16px;
    /* font-family: avali_scratchregular; */
    float: left;
    clear: left;
    margin: 5px;
    }
    #FONTCONTROLLER input {
    float: right;
    clear: right;
    margin: 5px;
    width: 1em;
    }
    #FONTCONTROLLER img {
    position: absolute;
    left: 50%;
    margin: 0;
    width: 24px;
    height: 24px;
    }
    </style>
    `;
    toggle.innerHTML += style;
    toggle.id = "FONTCONTROLLER";

    document.body.appendChild(toggle);

    const styleSheet = document.createElement("style");
    styleSheet.id = "AvaliScratchFontChanger";
    styleSheet.innerHTML = `
    * {
    font-family: avali_scratchregular !important;
    }
    `;
    document.body.appendChild(styleSheet);

    let f = function(){changeFont(document.body)};
    document.getElementById("toggleFontChange").checked = true;
    document.getElementById("toggleFontChange").onchange = f;
    document.getElementById("toggleLearnerMode").onchange = f;

    document.getElementById("fontRadio_scratch").onchange = f;
    document.getElementById("fontRadio_script").onchange = f;
    f();

    // make toggle box moveable
    toggle.style.height = toggle.offsetHeight + "px";
    var p1, p2, p3, p4;
    var dmu, domm;
    toggle.onmousedown = (e)=>{
        e = e || window.event;
        e.preventDefault();

        // get mouse pos
        p3 = e.clientX;
        p4 = e.clientY;

        dmu = document.onmouseup;
        domm = document.onmousemove;

        document.onmouseup = (e)=>{
            document.onmouseup = dmu;
            document.onmousemove = domm;
        }

        document.onmousemove = (e)=>{

            e = e || window.event;
            e.preventDefault();

            p1 = p3 - e.clientX;
            p2 = p4 - e.clientY;
            p3 = e.clientX;
            p4 = e.clientY;

            toggle.style.top = (toggle.offsetTop - p2) + "px";
            toggle.style.left = (toggle.offsetLeft - p1) + "px";

        }
    }

    // loopa
    // setInterval(f, 10000);

    // const observer = new MutationObserver(f);
    // observer.observe(document.body, { attributes: false, childList: true, subtree: true });

})();

function changeFont(element, setfont = null) {
    const fontLookup = {
        "scratch": "avali_scratchregular",
        "script": "avali_script",
    }
    if (setfont == null) setfont = document.getElementById("toggleFontChange").checked;
    var hover = document.getElementById("toggleLearnerMode").checked ? ":not(:hover)" : "";
    var style;
    if (setfont){
        style = `*${hover} {
    font-family: ${fontLookup[document.querySelector('input[name=font]:checked').value]} !important;
    }`;
    }
    else style = "";

    const styleSheet = document.getElementById("AvaliScratchFontChanger");
    styleSheet.innerHTML = style;

}

function changeFont_dep(element, setfont = null){
    const fontLookup = {
        "scratch": "scratch",
        "script": "script",
    }
    const learnerLookup = {
        "scratch": "learner",
        "script": "learner_script",
    }
    // get whether to set font
    if (setfont == null) setfont = document.getElementById("toggleFontChange").checked;
    // get font to set to
    var font, learner;
    if (document.querySelector('input[name=font]:checked') == null) {
        font = "scratch";
        learner = "learner";
    }
    else {
        font = fontLookup[document.querySelector('input[name=font]:checked').value];
        learner = learnerLookup[document.querySelector('input[name=font]:checked').value];
    }
    // add / remove font class(
    for (var key in fontLookup) {
        element.classList.remove(fontLookup[key]);
        element.classList.remove(learnerLookup[key]);
    }
    if (setfont) element.classList.add(document.getElementById("toggleLearnerMode").checked ? learner : font);
    // check for shadow root
    if (element.shadowRoot){
        if (!element.shadowRoot.getElementById("Avali Scratch Font")){
            let styleDiv = document.createElement("div");
            styleDiv.style.display = "none";
            styleDiv.innerHTML = style;
            element.shadowRoot.appendChild(styleDiv);
        }
        for (let i = 0; i < element.shadowRoot.children.length; i++){
            changeFont(element.shadowRoot.children[i], setfont);
        }
    }
    // go down tree
    for(var i=0; i < element.children.length; i++){
        changeFont(element.children[i], setfont);
    }
}
